cd "C:\zyh\work\宇树固件\real_unitree_r1_1.4.2" && cat > /tmp/disasm.py <<'EOF'
import sys
from elftools.elf.elffile import ELFFile
from capstone import *
from capstone.arm64 import *

path='module/webrtc_bridge/bin/unitreeWebRTCClientMaster'
f=open(path,'rb'); e=ELFFile(f)
symtab=e.get_section_by_name('.symtab')
syms={}
for s in symtab.iter_symbols():
    if s['st_value'] and s['st_size']:
        syms[s['st_value']]=(s.name,s['st_size'])
name=sys.argv[1]
addr=None;size=None
for a,(n,sz) in syms.items():
    if n==name: addr,size=a,sz
if addr is None:
    print("not found"); sys.exit(1)
# find section containing
code=None;base=None
for sec in e.iter_sections():
    if sec['sh_addr']<=addr< sec['sh_addr']+sec['sh_size'] and sec['sh_flags']&0x4:
        code=sec.data();base=sec['sh_addr'];break
off=addr-base
blob=code[off:off+size]
# build string resolver: read rodata
def read_str(a):
    for sec in e.iter_sections():
        if sec['sh_addr']<=a< sec['sh_addr']+sec['sh_size']:
            d=sec.data();o=a-sec['sh_addr']
            end=d.find(b'\x00',o)
            try: return d[o:end].decode('utf-8','replace')
            except: return None
    return None
md=Cs(CS_ARCH_ARM64,CS_MODE_ARM)
md.detail=True
adrp={}
for ins in md.disasm(blob,addr):
    line=f"{ins.address:x}: {ins.mnemonic} {ins.op_str}"
    extra=""
    if ins.mnemonic=='adrp':
        reg=ins.operands[0].reg; adrp[reg]=ins.operands[1].imm
    elif ins.mnemonic=='add' and len(ins.operands)==3 and ins.operands[2].type==ARM64_OP_IMM:
        sreg=ins.operands[1].reg
        if sreg in adrp:
            target=adrp[sreg]+ins.operands[2].imm
            st=read_str(target)
            if st: extra=f"  ; \"{st[:120]}\""
    elif ins.mnemonic=='bl':
        t=ins.operands[0].imm
        if t in syms: extra=f"  ; {syms[t][0]}"
        else:
            # plt
            extra=f"  ; ->{t:x}"
    print(line+extra)
EOF
python /tmp/disasm.py dataChannelOnMessageCallback > /tmp/dcmc.asm; wc -l /tmp/dcmc.asm
